"""Activity Selection — sort by finish time, take whatever still fits.

Time: O(n log n)   Space: O(n)
"""
from typing import List


class Solution:
    def maxActivities(self, start: List[int], finish: List[int]) -> int:
        activities = sorted(zip(finish, start))
        count, last_finish = 0, float("-inf")
        for end, begin in activities:
            if begin >= last_finish:
                count += 1
                last_finish = end
        return count
